import{_ as o,l as i,o as e,c as n,v as t,p as s,x as E,d,i as l,S as c}from"./chunks/framework.InCnrqk-.js";const C=JSON.parse('{"title":"IEEE 754","description":"","frontmatter":{"title":"IEEE 754","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/ieee-754.md","filePath":"cs/ieee-754.md","lastUpdated":1789023840000}'),p={name:"cs/ieee-754.md"};function h(m,a,A,B,_,u){const r=i("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="ieee-754" tabindex="-1">IEEE 754 <a class="header-anchor" href="#ieee-754" aria-label="Permalink to &quot;IEEE 754&quot;">​</a></h1><div class="epigraph"><p>若每台机器自己切尾数与指数，同一个算法会算出不同的比特；标准先统一位型，再谈舍入。</p><footer>—— 据 IEEE Std 754-1985；IEEE Std 754-2008；Patterson and Hennessy, Computer Organization and Design (RISC-V) 整理</footer></div><p>上一课<a href="/cs/fixed-and-float">定点与浮点</a>钉死了：非整数要么钉死小数点，要么让指数带着走。本课不重讲对阶，也不从「实数公理」另起。缺口是：浮点还只是形状。没有公共位域，寄存器里的串无法在编译器、ABI 和后课 ISA 之间对齐。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(x=\\pm m\\times 2^e\\) 仍有自由度：指数用偏置还是补码、尾数要不要隐藏位、零与溢出怎么编码。1980 年代以前各厂商切法不同，同一段源码换机器结果不同。缺口因此不是再解释「什么是浮点」，而是钉一套<strong>可交换的比特布局</strong>。</p><p>IEEE 754-1985 给出 <code>binary32</code> 与 <code>binary64</code>：1 位符号、偏置指数、规格化尾数的隐藏 \\(1\\)。2008 年把同一骨架写成更宽的交换格式，并澄清 NaN 载荷。本课只钉 32/64 位这张表，不把四则运算的每条舍入证明写完。</p><h3 id="nan-不是「出错整数」" tabindex="-1">NaN 不是「出错整数」 <a class="header-anchor" href="#nan-不是「出错整数」" aria-label="Permalink to &quot;NaN 不是「出错整数」&quot;">​</a></h3><p>补码溢出仍是某个整数编码。754 把指数全 1 留出来：尾数全 0 是无穷，非 0 是 NaN。比较与加法对 NaN 的规则与整数旗标不同：NaN 与任何值无序。把 NaN 当成「很大的数」，后课的分支会判错。</p><p><span class="marginnote">偏置指数让规格化数的大小比较可以先比符号再当无符号串比——这是 754 的设计，不是补码负权。非规格化数填满零附近的空隙，代价是有效位数下降。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><code>binary32</code>：指数 8 位，偏置 \\(127\\)；尾数 23 位，规格化时隐含首位 \\(1\\)，真尾数 24 位。<code>binary64</code>：指数 11 位，偏置 \\(1023\\)，尾数 52 位。数值</p> \\[(-1)^s\\cdot 1.f\\times 2^{E-\\mathrm{bias}}, \\]<p>\\(E\\) 全 0 时改走非规格化：\\(0.f\\times 2^{1-\\mathrm{bias}}\\)。舍入默认 round-to-nearest-even。RISC-V 的 <code>F</code>/<code>D</code> 扩展按这张表装寄存器；本课不把浮点指令表展开。</p>',13)),(e(),s(c,null,{default:E(()=>[l(r,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20SHAPE%5B%22%E6%B5%AE%E7%82%B9%EF%BC%9A%E5%B0%BE%E6%95%B0%E4%B9%98%E6%8C%87%E6%95%B0%22%5D%20--%3E%20BITS%5B%22754%EF%BC%9A%E7%AC%A6%E5%8F%B7%E3%80%81%E5%81%8F%E7%BD%AE%E6%8C%87%E6%95%B0%E3%80%81%E5%B0%BE%E6%95%B0%22%5D%0A%20%20BITS%20--%3E%20SPEC%5B%22%E8%A7%84%E6%A0%BC%E5%8C%96%20%2F%20%E9%9D%9E%E8%A7%84%E6%A0%BC%E5%8C%96%22%5D%0A%20%20BITS%20--%3E%20SPEC2%5B%22%E6%97%A0%E7%A9%B7%E4%B8%8E%20NaN%22%5D%0A%20%20SPEC%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E5%AD%97%E7%AC%A6%E7%BC%96%E7%A0%81%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>有了位型，相等先是比特相等，再才是数值相等：\\(-0\\) 与 \\(+0\\) 数值相等、比特不同。后课的哈希、序列化必须先说清比的是哪一种。加减对阶、乘加熔合（2008 的 FMA）改变舍入次数，数值可以与「先乘后加」不同；本课只承认这件事，不推导误差界。</p><p>规格化使多数值唯一表示，便于比较与译码。隐藏位省 1 比特精度，译码器必须会把它补回去——这是硬件代价，不是数学。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲十进制 754、不把软浮点实现写成代码，也不把异常旗标（无效、除零、上溢、下溢、不精确）接到后课的陷阱入口。那些要等<a href="/cs/exception-interrupt-entry">异常与中断入口</a>。字符与文本仍未进场。</p><p>后课默认：谈到单精度、双精度，位型是 IEEE 754 二进制格式；NaN 与无穷按指数全 1 读。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>IEEE 754 把浮点钉成可交换位型：偏置指数加隐藏位。</li><li>指数全 0 / 全 1 分别承担非规格化、零、无穷、NaN。</li><li>比较与哈希必须区分比特相等和数值相等。</li><li>出处：IEEE 754-1985 与 2008；Patterson and Hennessy, COD (RISC-V)。</li></ul>',8))])}const N=o(p,[["render",h]]);export{C as __pageData,N as default};
